"""Export an IR/entropy source profile into an OpenFOAM volScalarField."""
from __future__ import annotations
from pathlib import Path
import numpy as np


def write_source(path='sigmaIR', x=None, sigma=None):
    if x is None: x=np.linspace(-6,6,256)
    if sigma is None: sigma=np.exp(-x*x)
    p=Path(path); p.parent.mkdir(parents=True,exist_ok=True)
    with p.open('w') as f:
        f.write('/* OpenFOAM scalar source generated by geocusp */\n')
        f.write('/* Replace interpolation with your case-specific fvOptions/sourceTerm. */\n')
        for xi,si in zip(x,sigma): f.write(f'{xi:.16e} {si:.16e}\n')
    return p
if __name__=='__main__': print(write_source())
